fd.rendered(function() {
    fd.field('SubmittedByName').disabled = true;
    fd.field('SubmissionDate').disabled = true;
    if (!fd.field('SubmissionDate').value) fd.field('SubmissionDate').value = new Date();

    var questionNames = ['SecurityQuestion1','SecurityQuestion2','SecurityQuestion3'];
    var questions = ["What was the name of your first project or venture?", "What city hosted your first professional conference?", "What was the surname of an influential teacher or mentor?", "What was the name of your first research group or work team?", "What was the title of a memorable book from your studies?", "What was the name of the street where your first workplace was located?", "What was the name of your first professional organization?", "What city did you visit on your first business trip?", "What was the name of your first major client or partner?", "What was the topic of your first major presentation?"];
    var updating = false;
    function refreshQuestions() {
        if (updating) return;
        updating = true;
        var seen = {};
        questionNames.forEach(function(name) {
            var field = fd.field(name);
            if (field.value && seen[field.value]) field.value = null;
            if (field.value) seen[field.value] = true;
        });
        questionNames.forEach(function(name) {
            var field = fd.field(name);
            var current = field.value;
            var selectedElsewhere = {};
            questionNames.forEach(function(other) {
                if (other !== name && fd.field(other).value) selectedElsewhere[fd.field(other).value] = true;
            });
            field.widget.setDataSource(questions.filter(function(question) { return question === current || !selectedElsewhere[question]; }));
            if (current) field.value = current;
        });
        updating = false;
    }
    questionNames.forEach(function(name) { fd.field(name).$on('change', refreshQuestions); });
    refreshQuestions();

    var copiedName = '';
    function syncSubmitterName() {
        var name = [fd.field('FirstName').value, fd.field('LastName').value].filter(Boolean).join(' ');
        var target = fd.field('SubmittedByName');
        if (!target.value || target.value === copiedName) target.value = name || null;
        copiedName = name;
    }
    fd.field('FirstName').$on('change', syncSubmitterName);
    fd.field('LastName').$on('change', syncSubmitterName);
    if (!fd.field('SubmissionDate').value) fd.field('SubmissionDate').value = new Date();
    syncSubmitterName();
});
